{
  "type": "object",
  "required": [
    "QuoteStatus",
    "QuoteReference",
    "InsuranceSubType",
    "Premium",
    "Commission",
    "QuoteCreationDateTime"
  ],
  "properties": {
    "QuoteStatus": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEInsurance.AEInsuranceAcceptedByUserQuoteStatusCodes"
        }
      ],
      "description": "Quote status."
    },
    "QuoteReference": {
      "$ref": "#/components/schemas/AEInsurance.AEInsuranceQuoteReferenceType"
    },
    "InsuranceSubType": {
      "type": "string",
      "minLength": 1,
      "maxLength": 140,
      "description": "Insurance sub-type, describing the insurance type specific to the sector."
    },
    "Premium": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEInsurance.AEInsurancePremiumProperties"
        }
      ],
      "description": "Details of the quoted premium, as provided in the quote response."
    },
    "Commission": {
      "type": "object",
      "properties": {
        "CommissionAmount": {
          "allOf": [
            {
              "$ref": "#/components/schemas/AEInsurance.AEActiveCurrencyAmount"
            }
          ],
          "description": "The total monetary value of the commission paid to the TPP if the User proceeds with the quote application and purchases the policy based on the quote information provided."
        },
        "PaymentMethod": {
          "type": "string",
          "enum": [
            "DirectToTPP",
            "ThroughAPIHub"
          ],
          "description": "The method to be used to pay the commission to the TPP if the User elects to proceed with the application and successfully purchases the policy."
        }
      },
      "required": [
        "PaymentMethod"
      ],
      "description": "Details of the commission, as provided in the quote response."
    },
    "CustomerSalary": {
      "type": "string",
      "enum": [
        "Under4K",
        "Over4K"
      ],
      "description": "Confirmation whether the customer monthly salary is less than or greater than AED 4,000 each month. Required for Health Insurance."
    },
    "QuoteCreationDateTime": {
      "type": "string",
      "format": "date-time",
      "description": "The quote creation date and time, as supplied by the LFI in the property `CreationDateTime`."
    },
    "ExpirationDateTime": {
      "type": "string",
      "format": "date-time",
      "description": "The expiration date of the quote, as provided in the quote response, if provided by the LFI."
    },
    "PolicyIssuanceRequest": {
      "type": "object",
      "properties": {
        "CustomerVerification": {
          "type": "boolean",
          "description": "Broker request to complete capture of customer verification information and documents for this quote."
        },
        "Payment": {
          "type": "boolean",
          "description": "Broker request to host payment checkout."
        },
        "PolicyDocuments": {
          "type": "boolean",
          "description": "Broker request to provide policy documents to customer."
        }
      },
      "required": [
        "CustomerVerification",
        "Payment",
        "PolicyDocuments"
      ],
      "description": "Broker requests to handle following steps of policy issuance process."
    },
    "Documents": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AEInsurance.AEDocumentProperties"
      },
      "description": "Customer documents encoded for submission to the LFI. Omitted if not required or quote status is `ApplicationPending`."
    },
    "VerifiedDetails": {
      "type": "object",
      "properties": {
        "Policy": {
          "type": "object",
          "properties": {
            "Takaful": {
              "type": "boolean",
              "description": "Indicates whether the policy is Sharia compliant."
            },
            "CoverType": {
              "type": "string",
              "enum": [
                "Sole",
                "Joint"
              ],
              "description": "Indicates whether life Cover is required for a single person or jointly for multiple individuals"
            },
            "IsPolicyholderLifeAssured": {
              "type": "boolean",
              "description": "True (Yes) when that the Policyholder (customer) is also the Life Assured or one of the Life Assured, or false (No) when confirmation that the Policyholder and the Life Assured(s) are different"
            },
            "RelationshipToLifeInsured": {
              "allOf": [
                {
                  "$ref": "#/components/schemas/AEInsurance.AEInsuranceRelationshipToInsuredPartyCodes"
                }
              ],
              "description": "Required when the IsPolicyholderLifeAssured is false (No) to confirm the relationship between the Policyholder and Insured Person."
            },
            "ReasonDifferent": {
              "type": "string",
              "description": "Required when RelationshipToLifeInsured is Other to confirm that there is an insurable interest between the Policyholder and the Life Assured"
            },
            "TypeOfLifeInsurance": {
              "type": "string",
              "enum": [
                "WholeLifeInsurance",
                "LevelTermInsurance",
                "DecreasingTermInsurance"
              ],
              "description": "The type of life insurance required"
            },
            "InsurancePurpose": {
              "type": "string",
              "enum": [
                "PersonalCover",
                "FamilyProtection",
                "MortgageCover"
              ],
              "description": "The purpose of the life insurance cover"
            },
            "SumAssuredAmount": {
              "type": "object",
              "properties": {
                "Currency": {
                  "$ref": "#/components/schemas/AEInsurance.AEActiveOrHistoricCurrencyCode"
                },
                "Amount": {
                  "$ref": "#/components/schemas/AEInsurance.AEActiveOrHistoricAmount"
                }
              },
              "description": "The sum assured amount and currency."
            },
            "PolicyTerm": {
              "type": "string",
              "pattern": "^P(\\d+Y)?(\\d+M)?$",
              "format": "duration",
              "description": "The insurance policy term in years and months, using ISO 8601 compatible duration format",
              "example": "P2Y3M"
            },
            "PolicyStartDate": {
              "type": "string",
              "format": "date",
              "description": "Policy start date"
            },
            "PolicyEndDate": {
              "type": "string",
              "format": "date",
              "description": "Policy end date"
            },
            "IsFinanceAgainstPolicy": {
              "type": "boolean",
              "description": "Confirmation whether insurance cover is being taken out in connection with a finance / mortgage"
            },
            "FrequencyPremiumPayment": {
              "type": "string",
              "enum": [
                "Annually",
                "OneTime",
                "Monthly",
                "Quarterly",
                "BiAnnual",
                "Limited",
                "Other"
              ],
              "description": "Frequency of premium payments."
            },
            "PremiumPaymentTerm": {
              "type": "string",
              "pattern": "^P(\\d+Y)?(\\d+M)?$",
              "description": "Term of payments."
            },
            "RequiredAddons": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "minItems": 1,
              "description": "Required add-ons to be included in the quote based on Cover Name."
            }
          },
          "description": "Revised details, verified by the TPP.",
          "minProperties": 1
        },
        "InsuredParties": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "RelationshipToPolicyholder": {
                "allOf": [
                  {
                    "$ref": "#/components/schemas/AEInsurance.AEInsuranceRelationshipToInsuredPartyCodes"
